package com.theone.series;
import android.content.Intent;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class SeriesNavigationTest {
 @Test public void sourcesRemainSeparatedAndSeriesOnly()throws Exception{MediaRepository r=new MediaRepository(InstrumentationRegistry.getInstrumentation().getTargetContext());assertTrue(r.headersForUri("http://cqqwnnig.bulidns.com/series/test").isEmpty());assertEquals(1,r.headersForUri("https://rubenvanaggelen.com/the-one-remote-api/cinema.php?action=stream").size());try{r.load("movies");fail("Movie catalog must be rejected");}catch(java.io.IOException expected){}}
 @Test public void phoneSearchSeasonsEpisodesAndPlaybackWork()throws Exception{UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());Intent i=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);i.putExtra("series_test_mode",true);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(i)){
  assertTrue(device.wait(Until.hasObject(By.textContains("THE ONE SERIES")),10000));AtomicBoolean cancelled=new AtomicBoolean(false);scenario.onActivity(a->{try{a.registerBackgroundForTest(()->cancelled.set(true));}catch(java.io.IOException e){throw new RuntimeException(e);}});assertNull(device.findObject(By.text("Films")));assertNull(device.findObject(By.text("XXX")));device.findObject(By.clazz("android.widget.EditText")).setText("testserie 3");device.waitForIdle();assertTrue(device.wait(Until.hasObject(By.text("EN - Series testserie 3")),5000));device.findObject(By.text("EN - Series testserie 3")).click();assertTrue(device.wait(Until.hasObject(By.text("Seizoenen en afleveringen")),5000));device.findObject(By.text("Seizoenen en afleveringen")).click();assertTrue(device.wait(Until.hasObject(By.text("Seizoen 1")),5000));device.findObject(By.text("Seizoen 1")).click();assertTrue(device.wait(Until.hasObject(By.textContains("S01E01")),5000));device.findObject(By.textContains("S01E01")).click();assertTrue(device.wait(Until.hasObject(By.text("▶ Kijk")),5000));device.findObject(By.text("▶ Kijk")).click();AtomicBoolean playing=new AtomicBoolean(false);for(int n=0;n<40&&!playing.get();n++){scenario.onActivity(a->playing.set(a.isPlaybackReadyForTest()));Thread.sleep(250);}assertTrue("Episode renders a real video frame",playing.get());assertTrue("Episode playback cancels background downloads",cancelled.get());scenario.onActivity(a->assertTrue(a.isBackgroundPausedForTest()));device.pressBack();device.waitForIdle();scenario.onActivity(a->assertFalse(a.isBackgroundPausedForTest()));scenario.onActivity(a->a.findViewById(1006).performClick());assertTrue(device.wait(Until.hasObject(By.text("Seizoen 2")),5000));device.findObject(By.text("Seizoen 2")).click();assertTrue(device.wait(Until.hasObject(By.textContains("S02E01")),5000));scenario.onActivity(a->a.findViewById(1001).performClick());device.waitForIdle();assertNull(device.findObject(By.textContains("S02E01")));
 }}
 @Test public void languagePreferenceIsSelectableAndPersisted()throws Exception{android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();context.getSharedPreferences("the_one_series",android.content.Context.MODE_PRIVATE).edit().putString("preferred_language","en").commit();Intent intent=new Intent(context,MainActivity.class);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);intent.putExtra("series_test_mode",true);UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(intent)){scenario.onActivity(a->a.findViewById(1007).performClick());assertTrue(device.wait(Until.hasObject(By.text("Engels · standaard")),5000));assertTrue(device.wait(Until.hasObject(By.text("Nederlands")),5000));device.findObject(By.text("Nederlands")).click();assertTrue(device.wait(Until.hasObject(By.text("NL - Series testserie 1")),5000));assertEquals("nl",context.getSharedPreferences("the_one_series",android.content.Context.MODE_PRIVATE).getString("preferred_language",""));}finally{context.getSharedPreferences("the_one_series",android.content.Context.MODE_PRIVATE).edit().putString("preferred_language","en").commit();}}

 @Test public void languageMenuRemainsResponsiveWhileSelectionWorkerIsBusy()throws Exception{android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();context.getSharedPreferences("the_one_series",android.content.Context.MODE_PRIVATE).edit().putString("preferred_language","en").commit();Intent intent=new Intent(context,MainActivity.class);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);intent.putExtra("series_test_mode",true);UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());java.util.concurrent.atomic.AtomicReference<java.util.concurrent.CountDownLatch> gate=new java.util.concurrent.atomic.AtomicReference<>();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(intent)){scenario.onActivity(a->gate.set(a.pauseLanguageWorkerForTest()));AtomicBoolean blocked=new AtomicBoolean(false);for(int n=0;n<30&&!blocked.get();n++){scenario.onActivity(a->blocked.set(a.isLanguageWorkerBlockedForTest()));Thread.sleep(50);}assertTrue(blocked.get());scenario.onActivity(a->a.findViewById(1007).performClick());assertTrue(device.wait(Until.hasObject(By.text("Nederlands")),3000));device.findObject(By.text("Nederlands")).click();assertTrue("Published catalog stays visible while background work waits",device.wait(Until.hasObject(By.text("EN - Series testserie 1")),3000));scenario.onActivity(a->a.findViewById(1007).performClick());assertTrue("Language menu opens without waiting for catalog work",device.wait(Until.hasObject(By.text("Taalvoorkeur")),3000));device.pressBack();gate.get().countDown();assertTrue(device.wait(Until.hasObject(By.text("NL - Series testserie 1")),5000));}finally{if(gate.get()!=null)gate.get().countDown();context.getSharedPreferences("the_one_series",android.content.Context.MODE_PRIVATE).edit().putString("preferred_language","en").commit();}}

}
